# -*- coding: utf-8 -*-
import sys; sys.path.insert(0, "Tools/prd_ledger/86")
from _lib import c, table, save

c(14, "§3.1 table (verbatim); §3.1", "data-caveat", "Prioritised theme table (verbatim): " + table("## 3.1 The prioritised picture", 0) + " — praise and complaint are not separate populations: 152 reviews carry both a praise code and a bug code, 81 praise the design and report a defect — 'people who like the app describing what is broken in it'.", "n/a", "mixed", "praise_any 1,173 (65.71%, 4.54★); bug_any 469 (26.27%); monetisation_any 451 (25.27%); request_any 445 (24.93%); reliability 234 (2.71★); paywall_complaint 196 (2.76★); PAID 188 (10.53%); churn_any 98 (1.94★)", "none", "table", "generalisable", ["1345853521"], "", "")

c(15, "§3.2 visual model", "insight", "The visual model — beauty is functional for a habit app because it makes you want to open it: 'because the design is beautiful, motivation rises easily — a surprisingly important point' (jp 4★); 'So beautiful that it makes me want to just do the items so I can click them off'; 'if it isn't all there in front of me in an endearing way, then I slack off and say NOPE'; 'It changes habit tracking from a chore into a fun experience I enjoy and look forward to'; a Good Design Award recipient in broadcast graphics: 'one of the most thoughtfully designed apps I have used' (2026).", "photo-per-habit visual design", "praise", "PR_DESIGN 460 / 25.77%; PR_PHOTOS 97; union 523 / 29.30% / 4.36★", "build-free", "High-priority", "generalisable", ["3440039586", "1863740117", "2914912972", "1458034202", "13875862512"], "", "")

c(16, "§3.2 simplicity", "insight", "Simplicity is defined negatively — the absence of what rivals do: 'No frills, no fuss—no need to sit through way-too-long animations and stories and celebrations every time you do something' (4★); 'a check-in app doesn't need lots of frills; this is just right' (cn); 'It doesn't give you confetti or a cookie but it helps form that path in your brain'; 'Perfect app. Don't ruin it with clutter!'.", "minimal check-in, no celebrations", "praise", "PR_SIMPLE 361 / 20.22% / 4.68★", "product-rule", "High-priority", "generalisable", ["9243354141", "1881181884", "1795611028", "1427635117"], "", "")

c(17, "§3.2 best-in-category", "positioning", "Best-in-category and the named competition: PR_BEST 204 (11.43%, 4.78★ — the highest of any theme above 100); CMP_NAMED 48 (2.69%) — Way of Life, Momentum, Coach.me, Streaks, Done, Productive (2016), HabitBull, Habity, Shanbay (2017), iBetter, tiny routine, Strides (2018), Due (2019), Todoist, Day One, Evernote, Headspace, Notion (2022); Apple's Reminders, Calendar, Health and Activity named as both the thing replaced and the fallback; the corpus's most-voted review (38 up / 82): 'blew Momentum, Strides, and Way of Life out of the water… Momentum is too minimalistic (though I like their desktop sync, wink!) and Strides has a bubbly interface I can't stand' (2018).", "n/a", "praise", "PR_BEST 204 / 4.78★; CMP_NAMED 48; 18 rivals named", "none", "High-priority", "generalisable", ["3581019264", "1700023106", "1696422920"], "", "")

c(18, "§3.2 motivation and outcomes", "insight", "Motivation and outcomes: PR_MOTIVATION 184 (10.31%, 4.83★); PR_OUTCOME 106 (5.94%, 4.84★ — the highest mean in the corpus): 'App helped me drop 60lbs'; 'I haven't eaten meat in 50 days'; 'helped me quit drinking soda… over two months'; 'Makes learning 5 languages a breeze!'; '200 days of fitness' (cn); quitting smoking (a medical student, de); 'I've sustained habit-formation for about 6 years' (jp, 2026); and one on the mechanism — 'I started using this app to get a better grip on my depressive phases, and to sort days when I felt bad out of the streak. Over time it became easier to assess my successes' (de 5★) — describing the skip request as a mental-health tool.", "n/a", "praise", "PR_MOTIVATION 184 / 4.83★; PR_OUTCOME 106 / 4.84★", "none", "High-priority", "generalisable", ["2972263508", "1391838159", "1362961738", "1505874152", "4107813841", "1553250877", "13496344540", "1562859639"], "", "")

c(19, "§3.2 depth layer", "feature", "The depth layer — cards, stats, customisation, Health: U:depth_differentiator 192 (10.76%, 4.72★) — PR_CARDS 70, PR_STATS 65, PR_CUSTOM 87, PR_HEALTHKIT 38, PR_JOURNAL 24; 'EVERYTHING that is in your Apple Healthkit can be displayed… I tried all popular health dashboards and activity tracker, but this is miles ahead'; ''lead indicators' like calories consumed beside 'lag indicators' like your weight'; a weight graph from HealthKit and a distance-swum card (jp); 'I use it as sort of a memory box for things I've done'.", "paid cards with Health metrics, counters, charts, journal", "praise", "depth 192 / 10.76% / 4.72★; HEALTHKIT 38; CUSTOM 87; STATS 65; JOURNAL 24", "build-paid", "High-priority", "generalisable", ["1451883166", "2054180552", "1808438163", "1503438365"], "", "")

c(20, "§3.2 one-time pricing", "monetization", "One-time pricing as a product feature: PR_ONETIME 23 (4.61★), PR_WORTH 73 (4.09%, 4.84★), MON_DEFEND 44 (2.46%) — reviewers arguing against other reviewers' price complaints.", "one-time ~$4.99 (2016–2021)", "purchase-driver", "PR_ONETIME 23; PR_WORTH 73 / 4.84★; MON_DEFEND 44", "build-paid", "Very strong", "generalisable", ["1626756462", "1708111245"], "", "")

c(21, "§3.3 reliability; §7.3 reference", "must-never-break", "Reliability breakdown: U:reliability 234 (13.11%, 2.71★) — BUG_CRASH 126, BUG_PERF 70, BUG_LAUNCH 58, BUG_UPDATE 42 (2.35%, 2.55★: 'a specific update broke this'), BUG_GLITCH 26; five datable crash waves: launch (Mar 2016), iOS 9/10 (Oct–Nov 2016), Face ID / Touch ID (Mar 2018), iOS 12 / watchOS 5 (Sep 2018), the black-screen build (Nov 2022).", "n/a", "1★-burst", "reliability 234; CRASH 126; PERF 70; LAUNCH 58; UPDATE 42; 5 waves", "must-never-break", "High-priority", "generalisable", ["5953889344", "3259733326", "1386797586", "1477444905"], "", "")

c(22, "§3.3 reminders; §8.3", "must-never-break", "Reminders that do not fire — BUG_NOTIF 63 (3.53%, 2.57★), 2016-04-04 → 2025-02-10, ten years never fully fixed: 'notifications are straight up not working for habits. I have 3 set up and they never go off'; 'The idea of the app is to have reminders so you develop habits. Reminders are extremely hit or miss'; 'out of ten habits it notifies one or two' (br); and a specific reproducible behaviour reported independently in 2017 and 2021 — 'if I don't check in every single day, the reminders stop all together' — missing a day silences the reminder, the opposite of what a habit app should do; 10 of 63 say it makes the app unusable.", "reminders stop after a missed day", "complaint", "BUG_NOTIF 63 / 3.53% / 2.57★; unusable 10; stop-after-miss 2 (2017, 2021)", "must-never-break", "Very strong", "generalisable", ["1472871151", "7333847009", "12293267990", "7936221496", "1887236677"], "", "a reminder that stops after a missed day abandons the user at the moment they need it")

c(23, "§3.3 data loss; §8.4", "must-never-break", "Data loss — U:dataloss_any 55 (3.08%, 2.67★): BUG_DATALOSS 33, BUG_BACKUP 28, BUG_ICLOUD 17, BUG_SAVE 12; backup and restore is a paid feature, which makes these the most serious complaints — 12 of these reviewers also state they paid: 'this is the third time I've opened the app to find months worth of data has been randomly corrupted/lost… despite having paid extra to back it up' (1★); 'I lost my 3 years data due to an issue in restore backup' (it 1★); 'the crucial backup was overwritten and even the restore data was wiped' (jp, titled 'Farewell, Today'); 'iCloud was clearly on but there was no automatic backup — all the data is gone' (cn 1★); 'these people have lost ALL my information on 2 occasions' (pe 1★); REQ_ACCOUNT 3 ask for a login so history is not hostage to one device.", "paid iCloud/Dropbox backup that corrupts or overwrites", "1★-burst", "dataloss_any 55 / 3.08% / 2.67★; paid among them 12; REQ_ACCOUNT 3", "must-never-break", "Very strong", "generalisable", ["2955539119", "5866189908", "2168696471", "9310883434", "6432248651"], "", "")

c(24, "§3.3 navigation model; §8.8", "insight", "The navigation model people fight with: BUG_SWIPE 39 (2.18%) — horizontal swipe between habits conflicting with vertical scroll — 2016-03-11 → 2024-08-11 in seven languages, the single longest-running unfixed complaint ('about half the time, instead of going sideways… it starts going up', 2016; 'Same same since summer last year at least', 2018; 'apparently not improved for a year', 2019); with UX_FRICTION 41 (too many taps) and REQ_DASHBOARD 70 (3.92%, see all habits at once, 2016-03-21 → 2026-07-13) this is one complaint: 'the one-page-per-habit model does not scale past a handful of habits' — 'Requiring each habit to be its own page makes this impractical for tracking more than a small number of items' (2★); 'I have more than 30 habits to track… please minimize that dashboard so i could see all my habits at once' (2026, 2★).", "one full-screen page per habit; no overview", "complaint", "BUG_SWIPE 39 (10 years); UX_FRICTION 41; REQ_DASHBOARD 70 / 3.92% (10 years)", "must-have", "Very strong", "generalisable", ["1346490678", "2229824122", "3646704940", "1501989659", "14293434159", "2250385177"], "", "the signature design choice is also the scaling ceiling")

c(25, "§3.3 onboarding", "must-have", "Onboarding and comprehension: UX_CONFUSE 74 (4.15%), UX_ONBOARD 20 — people cannot find check-in ('I could never figure out how to check in', 2★), cannot understand the custom chart or counter, cannot tell a skipped day from a missed one ('I can not to figure out what different between skipped and not to check in'), cannot find the statistics ('I only stumbled on the charts in the profile section by accident!', 5★); the cost stated plainly: 'The statistics are in the profile. You can't start the app with the list of goals… So I deleted it; otherwise I'd have bought it' (ch 1★) — a confused user who was willing to pay.", "check-in gesture and stats undiscoverable", "blocked-conversion", "UX_CONFUSE 74 / 4.15%; UX_ONBOARD 20", "must-have", "Very strong", "generalisable", ["1659445486", "1708111245", "5692422621", "7249989187"], "", "")

c(26, "§3.4 table (verbatim); §3.4", "feature", "The standing request list — demands the product never answered (verbatim): " + table("## 3.4 Unmet needs", 0) + " — a home-screen widget never shipped (NC widget shipped 2016, lost 2021, restored 2021), an overview never, Infograph complications never, iPad never in 10 years, more cover photos never, more card types never, richer reminder control never, a timer never, back-fill partially then made harder, bad-habit tracking never despite the listing advertising it, Mac/web never, export partial, a note per check-in never, archive/pause never, sort added but slow, categories never, skip added but nobody understands it, auto check-in from Health never, an explicit missed-day mark never.", "n/a", "complaint", "REQ_DASHBOARD 70; WIDGET 47; WATCH 34; INTEGRATION 34; CARDS 29; FREQ 27; IPAD 27; NOTIF_OPTS 25; IMAGES 23; TIMER 18; BACKFILL 18; BREAKBAD 15; MAC 14; EXPORT 14; NOTE 12; ARCHIVE 11; SORT 11; CATEGORY 11; SKIP 11; AUTOCHECK 11; FAILMARK 6", "none", "table", "generalisable", ["2223367800", "3610997192", "7645092267"], "", "")

c(27, "§3.4 archive/pause; §8.6", "feature", "Archive/pause a habit — the most-upvoted request in the corpus (22 up / 36): 'could you add a way to stop a habit? Sometimes a habit is already formed or no longer needed, but currently you can only delete it, and all the data goes with it — a great pity' (cn 5★) — 'the design forces a user who succeeded to destroy their record of succeeding'; restated across five years and four languages (REQ_ARCHIVE 11 + REQ_SKIP 11 = 21); skip was added but nobody understands it; a depressive user uses skip to 'sort days when I felt bad out of the streak'.", "no archive; delete destroys history; skip exists but unexplained", "complaint", "REQ_ARCHIVE 11; REQ_SKIP 11; top-voted request 22/36", "must-have", "Meaningful", "generalisable", ["2223367800", "1562859639", "5692422621"], "", "")

c(28, "§3.4 bad habits; §8.7", "dont", "Bad-habit tracking — a marketing-to-product mismatch: the description says 'Quit bad habits and stay on track' and the feature does not exist (REQ_BREAKBAD 15, 2016 → 2026); 'if I only want to limit my intake to, say, two sodas a day, I can't both log each drink and show success for not going over the limit' (5★); 'the description talks about losing bad habits: we need an explanation. In what way does this app concern itself with our bad habits?' (fr 4★); USE_QUIT 16 are trying to use it that way anyway.", "listing promises quit-habit tracking; no limit/negative mode", "complaint", "REQ_BREAKBAD 15; USE_QUIT 16", "dont", "Emerging", "generalisable", ["7645092267", "5953889344"], "", "")

c(29, "§3.4 note per check-in", "feature", "A note per check-in — the second-most-upvoted request (31 up / 47): 'it would be great if each check-in could carry a note… to record it at that point in time. That way you can know yourself more accurately' (cn 5★); REQ_NOTE 12 (2017 → 2022), never shipped despite a journal card existing.", "journal card exists; per-check-in note does not", "complaint", "REQ_NOTE 12; votes 31/47", "build-free", "Emerging", "generalisable", ["3610997192"], "", "")

c(30, "§3.5 table (verbatim); §3.5", "timeline", "Churn — U:churn_any 98 (5.49%, 1.94★): CHURN_DELETE 40, CHURN_BLOCKED 43, CHURN_THREAT 13; what leavers cite (verbatim): " + table("## 3.5 Churn", 0) + " — 'In 2016 people left over the paywall. From 2018 they leave over reliability. That shift is the whole story of this product compressed into one table.'", "n/a", "churn", "churn_any 98 / 1.94★; reliability 32; watch 22; paywall 17; perf 17; notif 15; dataloss 14; stale 12", "none", "High-priority", "generalisable", ["2056463243", "3259733326", "1346837988", "1606690337"], "", "")

c(31, "§3.6; §8.11", "timeline", "Support: SUP_ASK 54 (3.03%) ask the developer a question in a review — a signal the in-app support path is not obvious; SUP_NORESP 25 (1.40%, 2.20★); against that PR_DEV 39 (4.59★) and, early on, an unusually responsive developer ('They reply very quickly and kindly', 2016; 'not only did I get a reply, the problem was fixed within days', 2017; 'Dev Team reacted quite quick… Changed my rating to 5 stars', 2018); FIX_CONFIRM 33 (4.76★) — 21 of 33 from before 2019: 'responsiveness is visibly the thing that used to convert angry reviewers into advocates, and it stopped'; by the end: 'haven't heard back from anyone in 6 months +' (2023); a three-week wait for a one-line 'import is currently not possible' (jp).", "responsive 2016–18, silent 2019–25", "mixed", "SUP_ASK 54; SUP_NORESP 25 / 2.20★; PR_DEV 39 / 4.59★; FIX_CONFIRM 33 / 4.76★ (21 pre-2019)", "do", "Very strong", "generalisable", ["1356064325", "1974586345", "3493496861", "10764479431", "3744435175"], "", "")

